merge into RRL_SCHEMA_MIGRATIONS t using(select '2026-10-12-339-per-sku-mark-matrix' MIGRATION_ID from dual)s on(t.MIGRATION_ID=s.MIGRATION_ID)when not matched then insert(MIGRATION_ID,DESCRIPTION,APPLIED_AT,APPLIED_BY,SCRIPT_NAME,ROLLBACK_SCRIPT,STATUS)values(s.MIGRATION_ID,'Per-SKU per-unit recipient profile matrix with current saved code version admission and per-lot quantities',sysdate,user,'apply.sql','rollback.sql','APPLIED');
